<script setup>
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {request,setToken,selectGroup} from './api'
import NodePanel from './components/NodePanel.vue'
const user=ref(null),group=ref(null),members=ref([]),discussions=ref([]),tab=ref('groups'),joined=ref(false),error=ref(''),busy=ref(false),modal=ref(''),register=ref(false),advisorQuestion=ref(''),advisorAnswer=ref(''),adminOverview=ref(null),adminRequests=ref([]),adminUsers=ref([])
const form=ref({email:'',password:'',nickname:'',join_key:'',host_name:'我的学习设备',title:'',body:'',avatar_url:'',oj_provider:'',oj_api_key:'',advisor_provider:'',advisor_api_key:'',current_password:'',new_password:'',group_name:'',group_description:''})
const catalog=ref([])
let groupEpoch=0
const online=computed(()=>members.value.filter(m=>m.online).length)
async function run(fn){error.value='';busy.value=true;try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function authenticate(){await run(async()=>{if(register.value)await request('identity','/auth/register','POST',form.value);const data=await request('identity','/auth/login','POST',form.value);setToken(data.access_token);user.value=data.user;form.value.password='';modal.value='';if(group.value){await restoreGroup();enter()}})}
async function restoreGroup(){try{await request('group','/group/heartbeat','POST');joined.value=true;await refresh()}catch{joined.value=false;members.value=[];discussions.value=[]}}
async function join(){await run(async()=>{await request('group','/group/join','POST',{...form.value,nickname:user.value.nickname});joined.value=true;form.value.join_key='';modal.value='';tab.value='discussion';await refresh()})}
async function refresh(){if(!joined.value)return;const epoch=groupEpoch;await request('group','/group/heartbeat','POST');if(epoch!==groupEpoch)return;const [m,d]=await Promise.all([request('group','/group/members'),request('group','/group/discussions')]);if(epoch!==groupEpoch)return;members.value=m;discussions.value=d}
async function publish(){await run(async()=>{await request('group','/group/discussions','POST',{title:form.value.title,body:form.value.body});form.value.title='';form.value.body='';modal.value='';await refresh()})}
async function saveProfile(){await run(async()=>{user.value=await request('identity','/users/me','PATCH',{nickname:form.value.nickname,avatar_url:form.value.avatar_url});modal.value=''})}
async function saveIntegrations(){await run(async()=>{await request('identity','/users/me/integrations','PUT',{oj_provider:form.value.oj_provider,oj_api_key:form.value.oj_api_key,advisor_provider:form.value.advisor_provider,advisor_api_key:form.value.advisor_api_key});modal.value=''})}
async function savePassword(){await run(async()=>{await request('identity','/users/me/password','POST',{current_password:form.value.current_password,new_password:form.value.new_password});form.value.current_password='';form.value.new_password='';modal.value=''})}
async function askAdvisor(){if(!advisorQuestion.value.trim())return;advisorAnswer.value='机器人顾问尚未接入模型 API，目前无法生成回答。';advisorQuestion.value=''}
async function createGroup(){await run(async()=>{await request('identity','/community/group-requests','POST',{name:form.value.group_name,description:form.value.group_description});form.value.group_name='';form.value.group_description='';modal.value='';error.value='群组创建申请已提交，等待服务部署。';await loadAdmin()})}
async function openAdmin(){tab.value='admin';await run(loadAdmin)}
async function loadAdmin(){if(user.value?.role!=='ADMIN')return;adminOverview.value=await request('identity','/admin/overview');adminRequests.value=await request('identity','/admin/group-requests');adminUsers.value=await request('identity','/admin/users')}
async function decideGroupRequest(id,status){await run(async()=>{await request('identity','/admin/group-requests/'+id,'PATCH',{status});await loadAdmin()})}
function enter(){if(!user.value){modal.value='auth';return}if(!joined.value){modal.value='join';return}tab.value='discussion';run(refresh)}
async function chooseGroup(entry){await run(async()=>{groupEpoch++;joined.value=false;members.value=[];discussions.value=[];group.value=null;selectGroup(entry);const info=await request('group','/group');if(info.id!==entry.id)throw new Error('群组目录与服务身份不匹配');group.value=info;if(user.value)await restoreGroup();sessionStorage.setItem('selected-group',entry.id);enter()})}
function logout(){groupEpoch++;setToken('');sessionStorage.removeItem('selected-group');user.value=null;joined.value=false;members.value=[];discussions.value=[];group.value=null;tab.value='groups'}
let interval
onMounted(async()=>{await run(async()=>{catalog.value=await request('identity','/community/groups');try{user.value=await request('identity','/users/me')}catch{setToken('')}const last=catalog.value.find(e=>e.id===sessionStorage.getItem('selected-group'));if(last&&user.value){selectGroup(last);const info=await request('group','/group');if(info.id!==last.id)throw new Error('群组服务身份不匹配');group.value=info;await restoreGroup()}});interval=setInterval(()=>{if(!document.hidden&&joined.value&&!busy.value)run(refresh)},30000)})
onUnmounted(()=>clearInterval(interval))
</script>
<template>
 <aside><a class="brand">◈ 算法同行<small>ALGO TOGETHER</small></a><p class="label">学习空间</p><button :class="{active:tab==='groups'}" @click="tab='groups'">◇ 群组入口</button><template v-if="joined"><p class="label compact">当前群组</p><button :class="{active:tab==='discussion'}" @click="tab='discussion'">☷ 讨论与复盘</button><button :class="{active:tab==='advisor'}" @click="tab='advisor'">✦ 机器人顾问</button><button :class="{active:tab==='members'}" @click="tab='members'">◎ 联网成员</button><button :class="{active:tab==='nodes'}" @click="tab='nodes'">⌘ 同步节点</button></template><button :class="{active:tab==='settings'}" @click="tab='settings'">⚙ 个人设置</button><button v-if="user?.role=== 'ADMIN'" :class="{active:tab=== 'admin'}" @click="openAdmin">管理后台</button><div class="aside-note">Spring Boot + Vue 3<small>独立群组服务 · 第二阶段</small></div></aside>
 <main><header><span>社区 / {{ {groups:'群组入口',discussion:'讨论与复盘',advisor:'机器人顾问',members:'联网成员',nodes:'同步节点',settings:'个人设置'}[tab] }}</span><div><span class="user-chip"><span class="avatar mini">{{user?.avatar_url?'◉':(user?.nickname?.slice(0,1)||'○')}}</span>{{user?.nickname||'尚未登录'}}</span><button class="secondary" @click="user?logout():modal='auth'">{{user?'退出登录':'登录 / 注册'}}</button></div></header>
 <div class="hero"><small>LEARN · SHARE · GROW</small><h1>{{tab==='groups'?'找到你的算法同伴':tab==='discussion'?'把思考分享给同伴':tab==='advisor'?'和你的算法顾问一起学习':tab==='nodes'?'管理你的同步设备':tab==='settings'?'管理个人资料与连接':'同伴就在这里'}}</h1><p>让每一个独立学习的时刻，都有同伴同行。</p></div>
 <p v-if="error" class="error" role="alert">{{error}}</p>
 <div v-if="joined" class="status">当前群组：{{group?.name}} <span>{{online}} 人在线</span><button class="secondary" :disabled="busy" @click="run(refresh)">同步成员</button></div>
 <section v-if="tab==='groups'"><div class="section-head"><h2>可连接的群组</h2><button :disabled="busy" @click="user?modal='create-group':modal='auth'">＋ 创建群组</button></div><div class="group-grid"><article v-for="entry in catalog" :key="entry.id" class="card"><div class="icon">⌘</div><h3>{{entry.name}}</h3><p>{{entry.description}}</p><div class="bottom"><span class="badge">{{joined&&group?.id===entry.id?'已连接':'独立群组服务'}}</span><button :disabled="busy" @click="chooseGroup(entry)">{{joined&&group?.id===entry.id?'进入群组 →':'连接群组 →'}}</button></div></article></div><div v-if="!catalog.length" class="empty">尚未加载群组目录，请检查身份服务是否启动。</div><p class="note">创建群组需要部署独立服务和数据库。当前按钮用于提交群组创建申请，管理员完成部署后会出现在可连接列表中。</p></section>
 <section v-if="tab==='discussion'"><div class="section-head"><h2>交流与复盘</h2><button v-if="joined" @click="modal='post'">＋ 发布讨论</button></div><div v-if="!joined" class="empty">先从群组入口加入一个群组。</div><div v-else-if="!discussions.length" class="empty">分享一个算法疑问，开始第一场讨论。</div><article v-for="post in discussions" :key="post.id" class="card post"><span class="muted">{{post.nickname}} · {{new Date(post.created_at).toLocaleString('zh-CN')}}</span><h3>{{post.title}}</h3><p>{{post.body}}</p></article></section>
 <section v-if="tab==='members'"><h2>联网成员</h2><div v-if="!joined" class="empty">加入群组后查看同伴。</div><div v-for="member in members" :key="member.user_id" class="member"><span class="avatar">{{member.nickname.slice(0,1)}}</span><div><strong>{{member.nickname}}</strong><small>{{member.host_name}}</small></div><span :class="['presence',{offline:!member.online}]">{{member.online?'● 在线':'● 离线'}}</span></div><p class="note">30 秒心跳同步，90 秒未收到心跳后显示离线。</p></section>
 <section v-if="tab==='advisor'" class="card advisor"><h2>群组机器人顾问</h2><p>顾问只在当前群组工作区内提供学习建议，可结合讨论内容、知识检查和个人目标。</p><div class="advisor-answer" v-if="advisorAnswer">{{advisorAnswer}}</div><textarea v-model="advisorQuestion" placeholder="例如：帮我分析这道题的复杂度"></textarea><button @click="askAdvisor">询问顾问</button><p class="note">请先在个人设置中配置顾问服务商和 API 密钥；密钥只保存于身份服务。</p></section>
 <section v-if="tab==='settings'"><h2>个人设置</h2><div class="settings-grid"><article class="card"><h3>资料与头像</h3><label>昵称<input v-model="form.nickname"></label><label>头像地址<input v-model="form.avatar_url" placeholder="https://... 或本地图片地址"></label><button @click="saveProfile">保存资料</button></article><article class="card"><h3>修改密码</h3><label>当前密码<input v-model="form.current_password" type="password"></label><label>新密码<input v-model="form.new_password" type="password" minlength="8"></label><button @click="savePassword">更新密码</button></article><article class="card"><h3>服务连接</h3><label>OJ 平台<select v-model="form.oj_provider"><option value="">未配置</option><option>Codeforces</option><option>AtCoder</option><option>Luogu</option></select></label><label>OJ API 密钥<input v-model="form.oj_api_key" type="password"></label><label>顾问服务商<input v-model="form.advisor_provider" placeholder="例如 OpenAI-compatible"></label><label>顾问 API 密钥<input v-model="form.advisor_api_key" type="password"></label><button @click="saveIntegrations">保存连接设置</button></article></div></section>
 <NodePanel v-if="tab==='nodes'" :key="group?.id||'none'" :joined="joined" />
 <section v-if="tab==='admin'"><div class="section-head"><h2>管理后台</h2><button :disabled="busy" @click="run(loadAdmin)">刷新</button></div><div class="admin-grid"><article class="card">用户 {{adminOverview?.users??'—'}}</article><article class="card">管理员 {{adminOverview?.admins??'—'}}</article><article class="card">群组 {{adminOverview?.configured_groups??'—'}}</article><article class="card">待处理 {{adminOverview?.pending_group_requests??'—'}}</article></div><h3>群组创建申请</h3><div v-if="!adminRequests.length" class="empty">暂无申请</div><div v-for="item in adminRequests" :key="item.ID" class="member"><div><strong>{{item.NAME}}</strong><small>{{item.DESCRIPTION}}</small></div><span class="badge">{{item.STATUS}}</span><template v-if="item.STATUS==='PENDING'"><button :disabled="busy" @click="decideGroupRequest(item.ID,'APPROVED')">批准</button><button class="secondary" :disabled="busy" @click="decideGroupRequest(item.ID,'REJECTED')">驳回</button></template></div><h3>账号列表</h3><div v-for="item in adminUsers" :key="item.ID" class="member"><div><strong>{{item.NICKNAME}}</strong><small>{{item.EMAIL}}</small></div><span class="badge">{{item.ROLE}}</span></div></section><footer>算法同行 · 目标驱动的算法学习社区</footer></main>
 <div v-if="modal" class="overlay"><div class="dialog" role="dialog" aria-modal="true"><div class="section-head"><h2>{{modal==='auth'?(register?'创建学习账号':'欢迎回来'):modal==='join'?'密钥加入群组':modal==='post'?'发布讨论':'申请创建群组'}}</h2><button class="secondary" @click="modal=''">✕</button></div><form @submit.prevent="modal==='auth'?authenticate():modal==='join'?join():modal==='post'?publish():createGroup()"><template v-if="modal==='auth'"><label>邮箱<input v-model="form.email" type="email" required></label><label>密码<input v-model="form.password" type="password" minlength="8" required></label><label v-if="register">昵称<input v-model="form.nickname" maxlength="40" required></label><button type="button" class="secondary" @click="register=!register">{{register?'已有账号？登录':'还没有账号？注册'}}</button></template><template v-if="modal==='join'"><label>群主分享的联网密钥<input v-model="form.join_key" type="password" minlength="16" required></label><label>设备名称<input v-model="form.host_name" maxlength="80" required></label></template><template v-if="modal==='post'"><label>标题<input v-model="form.title" maxlength="100" required></label><label>内容<textarea v-model="form.body" maxlength="20000" required></textarea></label></template><template v-if="modal==='create-group'"><label>群组名称<input v-model="form.group_name" maxlength="60" required></label><label>群组简介<textarea v-model="form.group_description" maxlength="500" required></textarea></label><p class="note">提交后需要部署者为此群组创建独立服务进程、数据库和联网密钥。</p></template><p v-if="error" class="error">{{error}}</p><button class="submit" :disabled="busy">{{busy?'处理中…':'确认'}}</button></form></div></div>
</template>



